import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const k=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Rakkii Cars User Guide","text":"Run the shop in Rakkii Ops","tagline":"Short, step-by-step guides. Pick your role and start with your day.","actions":[{"theme":"brand","text":"New here? Start here","link":"/start/getting-started"},{"theme":"alt","text":"What's new","link":"/whats-new"}]},"features":[{"title":"🔧 Technician","details":"Clock in, open your jobs, tick the bay checklist, send the car to QC and take the four QC photos.","link":"/technician/","linkText":"Your day in the bay"},{"title":"🤝 Sales agent","details":"Log inquiries, follow up on time, ask the desk to price parts, and check your commission.","link":"/sales/","linkText":"Your day in sales"},{"title":"🧰 Owner / desk","details":"Open a job, quote it, start work, bill, collect and release the car. Then the money, people and settings.","link":"/desk/","linkText":"Your day at the desk"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794621279000}`),i={name:"index.md"};function r(n,e,d,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h2 id="three-things-to-know-first" tabindex="-1">Three things to know first <a class="header-anchor" href="#three-things-to-know-first" aria-label="Permalink to &quot;Three things to know first&quot;">​</a></h2><ol><li><strong>The app tells you what to do next.</strong> Every job has a blue <strong>next-step button</strong> at the top (for example <strong>Save quote →</strong> or <strong>Release car →</strong>). Press it and the app takes you to the right place.</li><li><strong>Follow the names, not the colours.</strong> This guide uses the exact words on the buttons and tabs, in <strong>bold</strong>. The look of the app may change; the names stay.</li><li><strong>If a button is grey, the app says why.</strong> Read the line next to it. It names the missing step, for example &quot;Save quote is off: add a work line first.&quot;</li></ol><h2 id="one-job-start-to-finish" tabindex="-1">One job, start to finish <a class="header-anchor" href="#one-job-start-to-finish" aria-label="Permalink to &quot;One job, start to finish&quot;">​</a></h2><p>The path almost every job takes:</p><p><code>Booked</code> → <code>Quoted</code> → <code>Under repair</code> → <code>Quality check</code> → <code>Ready for pickup</code> → <code>Released</code> → <code>Done</code></p><p>The desk guide walks through it in <a href="/rakkii-cars-guide/desk/job/01-open-a-job">8 short steps</a>. Insurance and corporate jobs add a step or two. See <a href="/rakkii-cars-guide/desk/insurance-jobs">Insurance jobs</a> and <a href="/rakkii-cars-guide/desk/corporate-jobs">Corporate &amp; government jobs</a>.</p><h2 id="practising" tabindex="-1">Practising <a class="header-anchor" href="#practising" aria-label="Permalink to &quot;Practising&quot;">​</a></h2><p>Practise on the integration app with made-up customers and plates only:</p><ul><li>Staff app (Rakkii Ops): <code>https://rakkii-ops-int.web.app</code></li><li>Customer Portal: <code>https://rakkii-web-int.web.app</code></li></ul><div class="tip custom-block"><p class="custom-block-title">Can&#39;t find something?</p><p>Use the search box at the top of this guide (press <kbd>/</kbd>), or look in <a href="/rakkii-cars-guide/reference/statuses">Reference</a> for the detailed rules.</p></div>',10)])])}const u=t(i,[["render",r]]);export{k as __pageData,u as default};
